-- Add every non-empty fact from the supplied fifth batch. Russian/Russia
-- content is soft-hidden with isActive rather than deleted, preserving data
-- and historical delivery records for a future editorial re-enable.
WITH supplied_facts (ordinal, text) AS (
VALUES
  (401, $$Агентство национальной безопасности США (АНБ) привлекало известных писателей-фантастов (включая Ларри Нивена и Джерри Пурнелла) в качестве секретных консультантов во время Холодной войны. Их просили придумывать самые безумные сценарии развития технологий будущего, чтобы Пентагон мог подготовиться к потенциальным «сюрпризам» от СССР.$$),
  (402, $$Джон Стейнбек во время Второй мировой войны работал на американскую разведку (Управление стратегических служб). Он писал пропагандистские брошюры для европейского сопротивления и детальные инструкции по саботажу на немецких заводах.$$),
  (403, $$Ян Флеминг во время работы в британской военно-морской разведке разработал «Операцию Рут». План заключался в том, чтобы разбить немецкий бомбардировщик в Ла-Манше силами британских пилотов, одетых в немецкую форму, чтобы подоспевшие немецкие спасатели взяли их на борт, а англичане захватили их судно и выкрали шифровальную машину «Энигма». План сорвался, но лег в основу шпионских сюжетов о Джеймсе Бонде.$$),
  (404, $$Сомерсет Моэм в 1917 году был заслан британской разведкой МИ-6 в Петроград. Его секретная миссия заключалась в том, чтобы поддержать Временное правительство Александра Керенского, предотвратить приход большевиков к власти и удержать Россию в Первой мировой войне. Моэм не справился с задачей и едва успел бежать из страны перед Октябрьской революцией.$$),
  (405, $$Антуан де Сент-Экзюпери перед своим последним вылетом в 1944 году занимался составлением подробных разведывательных карт и фотосъемкой позиций немецких войск во Франции для авиации союзников.$$),
  (406, $$Грэм Грин был кадровым офицером британской разведки МИ-6 и работал в Африке под началом знаменитого Кима Филби — советского двойного агента, возглавлявшего контрразведку Англии. Грин использовал этот опыт для написания своих лучших реалистичных шпионских романов (например, «Наш человек в Гаване»).$$),
  (407, $$«Красная капелла» — советская агентурная сеть в Европе во время войны использовала в качестве ключей для шифрования радиограмм страницы популярных европейских романов. Чтобы расшифровать послание, нужно было иметь точно такое же издание книги той же недели выпуска.$$),
  (408, $$На Джоан Роулинг подала в суд американская писательница Нэнси Стуффер. Она утверждала, что Роулинг украла у неё идею «Гарри Поттера» из её книги 1984 года, где фигурировал персонаж по имени Ларри Поттер, а также использовалось слово Muggles (маглы). Суд полностью оправдал Роулинг, доказав, что Стуффер сфальсифицировала улики.$$),
  (409, $$Дэн Браун выиграл громкий суд против авторов книги «Святая Кровь и Священный Грааль» Майкла Бейджента и Ричарда Ли. Они обвиняли Брауна в плагиате их исторического расследования при написании «Кода да Винчи». Суд постановил, что исторические идеи и гипотезы не могут быть объектом авторского права. Браун в ироничной форме зашифровал имена истцов в анаграмму персонажа Ли Тибинга (Leigh Teabing).$$),
  (410, $$Суд над «Госпожой Бовари» — в 1857 году Гюстав Флобер предстал перед французским судом по обвинению в «оскорблении общественной морали и религии» за детальное описание супружеской измены его героини. Адвокат смог защитить писателя, и Флобер был оправдан, а скандал сделал роман феноменальным бестселлером.$$),
  (411, $$Манекенщица против Паланика — после выхода романа Чака Паланика «Невидимки» несколько топ-моделей пытались подать на автора в суд за то, что он якобы использовал их реальные биографии и пластические операции для создания образа изуродованной главной героини.$$),
  (412, $$Скандал с Джеймсом Фреем — в 2003 году его книга «Миллион маленьких кусочков» о жестокой наркозависимости и реабилитации стала мегахитом в США, её лично рекламировала Опра Уинфри. Позже журналисты выяснили, что Фрей выдумал 90% своей биографии, никогда не сидел в тюрьме и приукрасил свои страдания. Опра устроила писателю публичную порку в прямом эфире своего шоу, а издатели были вынуждены возвращать деньги обманутым читателям.$$),
  (413, $$Суд из-за «Трех мушкетеров» — соавтор Александра Дюма Огюст Маке подал на него в суд, требуя признать его законные права на соавторство и выплатить огромные роялти за «Трех мушкетеров», «Графа Монте-Кристо» и «Королеву Марго». Суд признал, что Маке собирал материалы, но текст был полностью переписан Дюма, поэтому Маке получил лишь денежную компенсацию, но не имя на обложке.$$),
  (414, $$Оскар Уайльд сам инициировал судебный процесс, который его погубил. Он подал иск о клевете против маркиза Куинсберри (отца своего любовника Альфреда Дугласа), который публично назвал Уайльда содомитом. Маркиз нанял частных детективов, собрал железные улики реальных связей писателя, выиграл суд, после чего Уайльда моментально арестовали и отправили на каторгу.$$),
  (415, $$Иск против Стивена Кинга — рок-музыкант Стивен Гросс подал в суд на писателя, утверждая, что Кинг украл его образ и историю жизни для создания персонажа стрелка Роланда Дискейна в цикле «Темная башня». Иск был отклонен как абсурдный.$$),
  (416, $$«Лолита» и наследники Нокса — когда Владимир Набоков опубликовал «Лолиту», критики заметили поразительное сходство фабулы с рассказом немецкого писателя Хайнца фон Лихберга «Лолита» (1916). Наследники Лихберга пытались заявить о плагиате, но эксперты доказали, что кроме имени девочки и общей темы влечения зрелого мужчины к подростку, тексты не имеют ничего общего.$$),
  (417, $$Личные блокноты, рукописи и поваренная книга Марии Кюри (открывательницы радия и полония) до сих пор настолько радиоактивны, что хранятся в свинцовых ящиках в Национальной библиотеке Франции. Любой исследователь, желающий ознакомиться с ними, обязан подписать отказ от претензий в случае болезни и надеть защитный костюм. Период полураспада Радия-226 составляет 1600 лет, так что книги будут убивать еще очень долго.$$),
  (418, $$В средние века для защиты ценных рукописей от насекомых и грызунов пергамент иногда обрабатывали растворами сулемы (хлорида ртути). Монахи, которые имели привычку слюнявить палец при перелистывании страниц, получали хроническое или острое отравление ртутью. Этот исторический факт лег в основу сюжета романа Умберто Эко «Имя розы».$$),
  (419, $$Книга, вызывающая галлюцинации — в XIX веке для отбеливания дешевой бумаги начали массово использовать хлор и химические соединения, которые при долгом хранении в сырых библиотеках выделяли токсичные споры плесени Aspergillus. Читатели, часами сидевшие над старыми фолиантами в непроветриваемых залах, сталкивались с сильной головной болью и яркими галлюцинациями.$$),
  (420, $$В древности и средние века для письма использовали железогалловые чернила, которые изготавливались из дубовых орешков (галлов) и железного купороса. Эти чернила со временем окислялись и буквально прожигали пергамент и бумагу насквозь, превращая текст в кружевные дыры.$$),
  (421, $$В старинных библиотеках, где книги не чистились десятилетиями, скапливался колоссальный объем экскрементов книжных клещей. Для библиотекарей прошлых веков хроническая астма и тяжелые поражения легких были профессиональными заболеваниями.$$),
  (422, $$В викторианской Англии в клей для книжных переплетов добавляли стрихнин, чтобы уберечь дорогие корешки от поедания крысами и мышами на складах.$$),
  (423, $$Во времена династии Цинь императорские указы и секретные свитки иногда покрывали тонким слоем сока ядовитого дерева лакового, который вызывал тяжелейшие химические ожоги и слепоту у любого, кто пытался вскрыть и прочесть документ без специальных шелковых перчаток.$$),
  (424, $$Николай Гоголь испытывал невероятную страсть к итальянской пасте. Находясь в Риме, он научился сам готовить макароны с сыром пармезан и сливочным маслом, причем добавлял туда столько специй, что друзья едва могли это есть. Писатель шутил, что в его жилах течет не кровь, а итальянский соус.$$),
  (425, $$Джордж Байрон был одержим своим весом и сидел на жесточайших диетах. Месяцами он питался исключительно тонкими ломтиками картофеля, вымоченными в уксусе, и пил содовую воду, чтобы поддерживать мертвенно-бледный, романтический цвет лица. Когда он срывался, он мог съесть огромный обед из четырех блюд за раз.$$),
  (426, $$Агата Кристи обожала пить сливки. Она могла выпить огромную чашку чистых жирных сливок во время написания детектива. При этом она терпеть не могла алкоголь и сигареты.$$),
  (427, $$Эрнест Хемингуэй придумал свой собственный рецепт коктейля «Смерть после полудня», который состоял из абсента и шампанского. Писатель утверждал, что нужно выпить три-четыре таких бокала медленно, чтобы поймать правильный писательский ритм.$$),
  (428, $$Александр Дюма-отец был не только гениальным писателем, но и профессиональным шеф-поваром. Его последним крупным жизненным трудом стал «Большой кулинарный словарь» на 1200 страниц, где собраны сотни рецептов со всего мира, включая инструкции по приготовлению мяса слона и лап кенгуру.$$),
  (429, $$Чарльз Диккенс обожал горячий пунш и сам мастерски его варил на глазах у гостей, превращая процесс в настоящее театральное шоу с поджиганием алкоголя и декламацией стихов.$$),
  (430, $$Жан-Поль Сартр для поддержания дикой интеллектуальной работоспособности ежедневно принимал огромные дозы коридpана (амфетамина), выкуривал по две пачки сигарет, выпивал литры черного кофе и несколько рюмок водки. Такой режим привел философа к полному истощению и слепоте в конце жизни.$$),
  (431, $$Вольтер тратил огромные суммы на импорт элитных кофейных зерен из колоний. Он утверждал, что разные сорта кофе помогают ему писать разные жанры: один сорт — для философских трактатов, другой — для злой сатиры.$$),
  (432, $$Лев Толстой после своего духовного перелома стал строгим вегетарианцем. Он полностью отказался от мяса, рыбы и яиц, утверждая, что «поедание живых существ превращает человека в зверя». Его жена Софья Андреевна втайне от мужа подливала мясной бульон в его овощные супы, боясь, что старик умрет от истощения.$$),
  (433, $$Франц Кафка был фанатичным приверженцем «флетчеризма» — модной системы питания, согласно которой каждый кусочек еды нужно было пережевывать ровно 32 раза перед проглатыванием. Из-за этого семейные обеды Кафки превращались в бесконечное, безмолвное жевание, что дико раздражало его отца.$$),
  (434, $$Цундoku (積ん読) — это официальный японский термин, который означает феномен покупки большого количества книг, которые затем просто складываются в стопки дома и никогда не читаются. Это не библиомания, а именно психологическое стремление окружать себя непрочитанными знаниями.$$),
  (435, $$Эффект спойлера — психологические тесты доказали, что люди, которые знают финал книги до начала чтения, получают от процесса больше удовольствия, чем те, для кого концовка становится сюрпризом. Знание финала позволяет мозгу расслабиться и внимательнее следить за деталями, стилем и развитием персонажей.$$),
  (436, $$Скорость чтения — средний взрослый человек читает со скоростью 200–250 слов в минуту. При такой скорости на прочтение стандартного романа объёмом в 100 тысяч слов уходит около 7–8 часов чистой концентрации.$$),
  (437, $$Книжный детокс — исследования Гарвардского университета показали, что чтение обычной печатной книги перед сном в течение 20 минут снижает уровень стресса на 68% (эффективнее, чем прослушивание музыки или прогулка), в то время как чтение с экрана смартфона из-за синего спектра света, наоборот, блокирует выработку мелатонина и ухудшает сон.$$),
  (438, $$Гендерный разрыв в чтении — согласно мировой статистике издательств, женщины покупают и читают художественную литературу примерно на 70% чаще, чем мужчины. Мужчины при этом лидируют в сегменте нон-фикшн, бизнес-литературы и исторических мемуаров.$$),
  (439, $$Самый заброшенный бестселлер — роман Стивена Хокинга «Краткая история времени» официально признан книгой, которую чаще всего покупают, но реже всего дочитывают до конца из-за сложности научных концептов.$$),
  (440, $$Библиотерапия — официальное направление в современной психотерапии, когда пациентам с депрессией, ПТСР или повышенной тревожностью прописывают чтение конкретных художественных произведений для проработки их внутренних психологических травм через сопереживание героям.$$),
  (441, $$Запах электронных книг — несколько парфюмерных брендов (включая Demeter и Karl Lagerfeld) выпустили духи с ароматом «старой книги» и «свеженапечатанной бумаги», так как опросы показали, что главным фактором отказа людей от перехода на электронные читалки является отсутствие тактильного и обонятельного контакта с бумагой.$$),
  (442, $$Книги-компаньоны — в крупных городах Японии и Южной Кореи набирают популярность отели и кафе «для одинокого чтения», куда запрещено приходить компаниями, разговаривать и пользоваться телефонами. Люди платят за возможность несколько часов посидеть в абсолютной тишине среди книжных полок.$$),
  (443, $$Миф о Сальери — Александр Пушкин в своей маленькой трагедии «Моцарт и Сальери» зацементировал миф о том, что завистливый Антонио Сальери отравил гениального Моцарта. В реальности Сальери был успешным, богатым и очень уважаемым композитором, учителем Бетховена, Листа и Шуберта, который искренне любил Моцарта и помогал его семье после его смерти. Миф настолько въелся в культуру, что в 1997 году в Милане прошел официальный судебный процесс, на котором суд присяжных посмертно полностью оправдал Сальери.$$),
  (444, $$Миф о короле Артуре — в литературе Артур изображается как благородный рыцарь в сияющих латах, заседающий за Круглым столом в замке Камелот. Исторический прототип Артура (если он существовал) был вождем бриттов в VI веке, который воевал против англосаксов в грязных кожаных доспехах, не имел никакого Камелота и лат, так как классическое рыцарство появилось на 500 лет позже.$$),
  (445, $$Шерлок Холмс не носил охотничью кепку — Артур Конан Дойл ни разу в своих текстах не упоминал, что Холмс носит знаменитую двухкозырку (deerstalker hat). Этот образ полностью придумал иллюстратор Сидни Пэджет, который рисовал картинки для журнала The Strand, основываясь на своей личной привязанности к этой кепке. Из иллюстраций образ перекочевал в кино.$$),
  (446, $$Миф о Франкенштейне — 90% людей, не читавших книгу Мэри Шелли, называют Франкенштейном зеленокожего монстра с болтами в шее. В романе Франкенштейн — это фамилия молодого ученого (Виктор Франкенштейн), который создал ожившее существо. Сам монстр в книге не имеет имени и называется просто «Созданием», «Демоном» или «Монстром».$$),
  (447, $$Три мушкетера не были друзьями в реальности — реальные прототипы героев Дюма (д'Артаньян, Атос, Портос и Арамис) жили в разное время, имели огромную разницу в возрасте и никогда не служили в одной четверке. Атос (Арман де Сильэг) погиб на дуэли, когда реальный д'Артаньян (Шарль де Бац) только приехал в Париж записываться в мушкетеры.$$),
  (448, $$Миф о Робин Гуде — в балладах Робин Гуд грабит богатых и отдает деньги бедным. В самых ранних средневековых текстах Робин Гуд — жестокий йомен (свободный крестьянин), который грабит богатых церковников исключительно ради собственной наживы и мести шерифу, а крестьянам не отдает ни единого пенни. Благородный налет романтизма образу придали писатели XIX века.$$),
  (449, $$Покахонтас и Джон Смит — благодаря книгам и мультфильмам мир верит в трагическую любовь индейской принцессы Покахонтас и английского капитана Джона Смита. Когда Смит прибыл в Вирджинию, Покахонтас было всего 10–11 лет. Она действительно спасла его от казни, но это был традиционный индейский ритуал «усыновления» чужака племенем, и никаких романтических отношений между ними не было.$$),
  (450, $$Миф о спасении Рима гусями — историк Тит Ливий в своей «Истории Рима» описал, как священные гуси храма Юноны разбудили защитников Капитолия во время ночного штурма галлов. Современные военные историки доказали, что гуси не могли поднять такой шум, который перекрыл бы крики штурмующих, и, скорее всего, римская стража просто проспала, а легенду выдумали, чтобы скрыть позор халатности часовых.$$),
  (451, $$Миф о сожжении Александрийской библиотеки — принято считать, что величайшую библиотеку древности за один раз сжег либо Юлий Цезарь, либо христианские фанатики, либо халиф Умар. Исторические исследования доказали, что библиотека погибала медленно, на протяжении веков, от банального отсутствия финансирования, сырости, гражданских войн и постепенного расхищения свитков чиновниками.$$),
  (452, $$«Элементарно, Ватсон!» — эта фраза стала визитной карточкой Шерлока Холмса. Однако в оригинальном каноне Конан Дойла Холмс часто говорит слово «Элементарно» и часто говорит «Ватсон», но эти два слова ни разу не стоят в одном предложении. Фразу впервые соединил актер Уильям Джиллетт в театральной пьесе 1899 года, которую Конан Дойл лично одобрил.$$),
  (453, $$Слово «Панталоны» пришло в литературу и язык из итальянской комедии дель арте, где персонаж Панталоне (старый скупой венецианский купец) всегда ходил в узких длинных красных штанах. Название персонажа закрепилось за элементом одежды.$$),
  (454, $$Слово «Синекура» (выгодная должность, не требующая особого труда) пришло из средневековой церковной литературы. Буквально с латыни sine cura переводится как «без заботы» (имелась в виду церковная должность, которая приносила доход, но не требовала заботы о душах прихожан).$$),
  (455, $$Имя Дороти (главная героиня «Волшебника Страны Оз») Фрэнк Баум выбрал в память о своей маленькой племяннице Дороти Гейдж, которая умерла во младенчестве прямо во время написания первой книги. Писатель хотел, чтобы имя девочки жило вечно.$$),
  (456, $$Слово «Интеллигенция» в его современном понимании (как слой образованных людей, обладающих высокой моральной ответственностью) ввел в русский и мировой оборот писатель и журналист Пётр Боборыкин в 1860-х годах. До этого латинское слово intelligentia означало просто «понимание» или «разум».$$),
  (457, $$Слово «Шовинизм» пошло от фамилии вымышленного (или полулегендарного) солдата наполеоновской армии Никола Шовена. Он стал героем множества французских комедий и рассказов XIX века, где изображался как слепой, фанатичный патриот, готовый боготворить Наполеона даже в нищете и калечестве.$$),
  (458, $$Имя Памела было полностью выдумано английским поэтом Филипом Сидни для его пасторального романа «Аркадия» (1590). Писатель составил его из двух греческих корней, означающих «вся сладость».$$),
  (459, $$Слово «Цербер» (Кербер) в греческой литературе означает трехглавого пса, охраняющего вход в подземный мир. Любопытно, что с древнеиндоевропейского корня имя собаки переводится буквально как «Пятнистый». То есть Аид, владыка подземного мира, назвал свое чудовище просто Кляксой или Пятнышком.$$),
  (460, $$Фрэнк Герберт перед написанием «Дюны» провел масштабное исследование воздействия психоделических грибов на человеческий мозг. Концепт «пряности» (спайса), расширяющей сознание и позволяющей навигаторам видеть будущее для межзвездных перелетов, во многом вдохновлен его личными экспериментами с шаманскими практиками мексиканских индейцев.$$),
  (461, $$Айзек Азимов панически боялся летать на самолетах. За всю свою жизнь он поднялся на борт самолета всего дважды (и то во время службы в армии под конвоем). Все свои путешествия по миру великий фантаст совершал исключительно на круизных лайнерах или поездах.$$),
  (462, $$Рэй Брэдбери до конца своих дней отказывался пользоваться персональным компьютером и интернетом. Он утверждал, что компьютеры — это «бездушные печатные машинки с подсветкой», которые лишают писателя тактильного контакта с текстом, и набирал все романы на механической машинке Smith Corona.$$),
  (463, $$Джон Толкин обожал курить трубку и утверждал, что привычка хоббитов курить «трубочное зелье» — это его автобиографическая черта. Он тратил огромные суммы на покупку элитных сортов вирджинского табака и коллекционировал глиняные и деревянные трубки.$$),
  (464, $$Стивен Кинг в 1999 году был сбит минивэном во время своей традиционной пешей прогулки у озера. Писатель получил тяжелейшие переломы и едва выжил. Позже он выкупил тот самый сбивший его автомобиль за 1500 долларов исключительно для того, чтобы лично разбить его кувалдой вдребезги на заднем дворе своего дома, предотвратив превращение машины в сувенир для фанатов на аукционах.$$),
  (465, $$Уильям Гибсон при написании романа «Нейромант» придумал слово «Матрица» для описания всемирной компьютерной сети. Когда спустя 15 лет братья Вачовски сняли свой культовый фильм «Матрица», они официально признали, что визионерская концепция Гибсона стала их главным источником вдохновения.$$),
  (466, $$Артур Кларк долгие годы жил на Шри-Ланке, где профессионально занимался дайвингом и подводной археологией. Он открыл руины затонувшего древнего храма и несколько затонувших кораблей, утверждая, что подводный мир успокаивает его разум гораздо лучше, чем размышления о далеком космосе.$$),
  (467, $$Филип Дик в последние годы жизни был убежден, что Римская империя никогда не падала, а современный мир — это масштабная технологическая иллюзия («черная железная тюрьма»), созданная для сокрытия того факта, что на дворе до сих пор идет I век нашей эры. Эта параноидальная идея легла в основу его культового романа «Валис».$$),
  (468, $$Джордж Мартин коллекционирует миниатюрных оловянных солдатиков и масштабные диорамы средневековых замков. В его рабочем кабинете установлены огромные столы, на которых расставлены тысячи фигурок рыцарей, с помощью которых он наглядно просчитывает тактику сражений и перемещения армий в «Песне Льда и Пламени».$$),
  (469, $$Дуглас Адамс был хроническим прокрастинатором и постоянно срывал сроки сдачи рукописей издателям. Его личный агент однажды запер писателя в гостиничном номере на три недели, приставив к двери охрану и запретив выпускать Адамса до тех пор, пока он не допишет финальные главы романа «Всего хорошего, и спасибо за рыбу!».$$),
  (470, $$«Кодекс Ужэла» (Codex Uzuel) — манускрипт XIV века, найденный в Португалии, примечателен своими полями. Средневековый монах-переписчик, которому было дико скучно выполнять монотонную работу, разрисовал поля рукописи карикатурами, изображающими боевых улиток, штурмующих замки, и зайцев, берущих в плен рыцарей. Этот феномен называется «маргиналии».$$),
  (471, $$Свитки папируса из Наг-Хаммади — коллекция раннехристианских и гностических текстов (включая тайное Евангелие от Фомы), обнаруженная в 1945 году египетским крестьянином Мухаммедом Али. Книги были сложены в большой глиняный кувшин, запечатанный воском. Находка полностью перевернула представления историков о раннем христианстве.$$),
  (472, $$«Эфесская библиотека Цельса» — одна из крупнейших библиотек древнего мира (хранила до 12 тысяч свитков), построенная в Риме в честь губернатора Цельса. Уникальность здания заключалась в том, что стены были двойными, с воздушной прослойкой между ними, что защищало хрупкие папирусы от влажности и резких перепадов температур.$$),
  (473, $$«Книга Диковинок» (Book of Curiosities) — арабский манускрипт XI века, содержащий уникальные, детализированные карты звездного неба и побережья Средиземного моря. Это старейший сохранившийся атлас, где навигационные карты снабжены подробными текстовыми описаниями портов, мелей и пиратских укрытий.$$),
  (474, $$Эффект стирания пергамента — в средние века из-за дороговизны кожи животных монахи часто брали старые языческие рукописи (тексты Цицерона, Горация, Тацита), смывали или соскабливали старый текст специальным химическим раствором и писали поверх молитвы. Такие книги называются «палимпсесты». Современные ученые с помощью инфракрасных сканеров легко восстанавливают первоначальный античный текст.$$),
  (475, $$Первая библиотека на Руси была основана князем Ярославом Мудрым в 1037 году при Софийском соборе в Киеве. Она насчитывала несколько сотен рукописных книг, переведенных с греческого языка на старославянский. Судьба этой библиотеки после монгольского нашествия до сих пор неизвестна.$$),
  (476, $$«Кодекс Амиатинский» (Codex Amiatinus) — самая старая сохранившаяся рукопись полной Вульгаты (латинского перевода Библии), созданная в Англии в начале VIII века. Книга имеет колоссальные размеры: её вес составляет более 35 кг, а для создания пергамента потребовалось забить более 500 телят.$$),
  (477, $$«Манускрипт из Тимбукту» — тысячи древних исламских рукописей по астрономии, медицине, праву и математике, хранившиеся в частных домах жителей Мали с XIV века. Во время гражданской войны в 2012 году местные библиотекари совершили подвиг: они тайно, на телегах и лодках, вывезли более 350 тысяч рукописей из зоны боевых действий и спрятали их в столице страны, спасши мировое наследие от уничтожения радикалами.$$),
  (478, $$Книга, написанная на шелке — в Китае в гробнице Мавандуй (II век до н.э.) были найдены уникальные трактаты по медицине и даосизму, написанные тушью на тончайших отрезах натурального шелка. Благодаря консервации в герметичном гробу ткань и текст сохранились в идеальном состоянии спустя две тысячи лет.$$)
)
INSERT INTO "philology_facts" ("id", "text", "category", "characterEmotion", "updatedAt")
SELECT
  'lily-library-' || lpad(ordinal::text, 5, '0'),
  text,
  CASE WHEN ordinal BETWEEN 453 AND 459 THEN 'PHILOLOGY' ELSE 'LITERATURE' END,
  CASE ordinal % 3 WHEN 1 THEN 'THOUGHTFUL' WHEN 2 THEN 'SURPRISED' ELSE 'JOYFUL' END,
  CURRENT_TIMESTAMP
FROM supplied_facts;

-- Do not delete this content: pause every editorial card about Russia,
-- Russian authors, Russian-language vocabulary, the USSR, or Soviet history.
-- The Lily selector already requires isActive = true, so the change takes
-- effect immediately for new facts while remaining fully reversible.
UPDATE "philology_facts"
SET "isActive" = FALSE, "updatedAt" = CURRENT_TIMESTAMP
WHERE "isActive" = TRUE
  AND "text" ~* '(росси|русск|ссср|советск|большевик|петроград|кремл|сталин|пастернак|достоевск|толст|пушкин|гогол|лермонтов|чехов|есенин|маяковск|тургенев|некрасов|гумилев|ахматов|мандельштам|зощенко|салтыков|жуковск|грибоедов|булгаков|бунин|куприн|горьк|фет|фонвизин|тютчев|жданов|солженицын|стругацк|ильф|петров|набоков|чуковск|крылов|беляев|акунин|гайдар|блок|волошин|бендер|ппш|живаго|облонск|мюнхгаузен)';

